mapper.select:
SELECT p.post_id AS postId, p.user_id AS userId, u.username AS authorName, p.title AS title, p.topic AS topic, p.content AS content, p.image_url AS imageUrl, p.goods_id AS goodsId, g.goods_name AS goodsName, p.like_count AS likeCount, p.comment_count AS commentCount, p.view_count AS viewCount, p.create_time AS createTime, p.update_time AS updateTime, (cl.like_id IS NOT NULL) AS liked FROM community_post p LEFT JOIN `user` u ON p.user_id = u.user_id LEFT JOIN goods g ON p.goods_id = g.goods_id LEFT JOIN community_like cl ON cl.post_id = p.post_id AND cl.user_id = #{currentUserId}
AND p.title LIKE CONCAT('%', #{keyword}, '%')
AND p.topic = #{topic}
ORDER BY p.like_count DESC, p.view_count DESC, p.post_id DESC
ORDER BY p.create_time DESC, p.post_id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM community_post p
AND p.title LIKE CONCAT('%', #{keyword}, '%')
AND p.topic = #{topic}

mapper.update:
UPDATE community_post
SET view_count = view_count + 1
WHERE post_id = #{postId}

UPDATE community_post
SET like_count = (
    SELECT COUNT(*) FROM community_like WHERE post_id = #{postId}
)
WHERE post_id = #{postId}

UPDATE community_post
SET comment_count = (
    SELECT COUNT(*) FROM community_comment WHERE post_id = #{postId}
)
WHERE post_id = #{postId}
